from scipy.interpolate import PchipInterpolator
path=Path('/workspace/C1_contact_coupe/CONTACT_C1.json');c=json.loads(path.read_text());motion=c['motion'];x=np.arange(401)/10;P=np.array([m['contact']for m in motion]);N0=np.array([m['normal']for m in motion]);interp=PchipInterpolator(x,P,axis=0);coef=interp.c.transpose(1,0,2)*np.array([.001,.01,.1,1])[None,:,None];dense=[];maxangle=0;maxplane=0
for phase in np.linspace(0,40,1601):
 i=min(399,int(phase*10));f=phase*10-i;n=unit(N0[i]*(1-f)+N0[i+1]*f);p=interp(phase);hh=hits(p+3*n,-n);hh=[h for h in hh if h[0]<6];assert hh,phase;dist,face,p=min(hh,key=lambda h:np.linalg.norm(h[2]-p));dense.append(p.tolist());maxplane=max(maxplane,abs((p-A[face])@N[face]));q=np.array(motion[i]['target'])*(1-f)+np.array(motion[i+1]['target'])*f;angle=np.degrees(np.arccos(np.clip(-n@unit(q-p),-1,1)));maxangle=max(maxangle,abs(angle-55))
